5	
6	namespace seed_b_backend.Api.Services;
7	
8	public class OrderService(AppDbContext db) : IOrderService
9	{
10	    public async Task<OrderCreationResult> CreateOrderAsync(OrderCreateDto dto, CancellationToken cancellationToken = default)
11	    {
12	        if (dto.Positionen is null || dto.Positionen.Count == 0)
13	        {
14	            return OrderCreationResult.Fail("Der Warenkorb ist leer.");
15	        }
16	
17	        foreach (var pos in dto.Positionen)
18	        {
19	            if (pos.Menge < 1)
20	            {
21	                return OrderCreationResult.Fail($"Ungültige Menge für Produkt {pos.ProduktId}.");
22	            }
23	        }
24	
25	        var resolvedItems = new List<(Offer Offer, PositionCreateDto Position)>();
26	        foreach (var pos in dto.Positionen)
27	        {
28	            var offer = await db.Offers
29	                .Include(o => o.Product)
30	                .Include(o => o.Supplier)
31	                .FirstOrDefaultAsync(o => o.ProductId == pos.ProduktId && o.SupplierId == pos.LieferantId, cancellationToken);
32	
